body.onloadscript:

        	if(Sepoa.request){
	            var functionName = Sepoa.request.FUNCTION_NAME;
	            var transactionCode = Sepoa.request.TRANSACTION_CODE;
	            doCreateTabbar(functionName, transactionCode);
        	}

userscript.function:

            doServiceAjax('sepoa.svc.admin.IFH_001', 'CONNECTION', 'doFindTable', {
                FUNCTION_NAME: functionName
            }, function(so) {
                if (so.status == 1) {
                    var soResult = new SepoaFormater(so.result[0]);

                    if(soResult.getArrayMap().length < 1){
                    	Alert(Sepoa.cache.text.get('IFH_003.MESSAGE001'));
                    	selfObj.close();
                    }else{
	                    soResult.getArrayMap().forEach(function(table) {
	                        tabbarObj.addTab(table.TABLE_NAME, table.TABLE_NAME);
	                        tabbarObj.cells(table.TABLE_NAME).attachURL("/Admin/InterfaceHistory/InterfaceHistoryTabGrid.sux?TABLE_NAME="+table.TABLE_NAME+"&TRANSACTION_CODE="+transactionCode);
	                    })

	                    tabbarObj.tabs(soResult.getArrayMap()[0].TABLE_NAME).setActive();
                    }
                } else {
                    Alert(Sepoa.cache.text.get('MESSAGE.1002'));
                    return false;
                }
            });
